resources.preRequestScript:
const formatar = instante => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(instante);
const diaDeslocado = dias => formatar(new Date(Date.now() + dias * 86400000));
insomnia.collectionVariables.set('execucao', String(Date.now()));
insomnia.collectionVariables.set('data_hoje', diaDeslocado(0));
insomnia.collectionVariables.set('data_retroativa', diaDeslocado(-3));
insomnia.collectionVariables.set('data_inicio_do_periodo', diaDeslocado(-6));
insomnia.collectionVariables.set('data_futura', diaDeslocado(2));

resources.afterResponseScript:
insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
insomnia.test('Emissor é o endereço público do Keycloak', () =>
    insomnia.expect(insomnia.response.json().issuer).to.eql(insomnia.collectionVariables.get('keycloak_url') + '/realms/' + insomnia.collectionVariables.get('realm')));

insomnia.test('Keycloak emite o token', () => insomnia.expect(insomnia.response.code).to.eql(200));
const corpo = insomnia.response.json();
insomnia.collectionVariables.set('token_loja_centro', corpo.access_token);
const conteudo = JSON.parse(atob(corpo.access_token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')));
insomnia.test('Token traz o comerciante c-001', () => insomnia.expect(conteudo.comerciante_id).to.eql('c-001'));
insomnia.test('Token tem a audiência verity-api', () => insomnia.expect([].concat(conteudo.aud)).to.include('verity-api'));
insomnia.test('Token assinado com RS256', () => insomnia.expect(JSON.parse(atob(corpo.access_token.split('.')[0].replace(/-/g, '+').replace(/_/g, '/'))).alg).to.eql('RS256'));

insomnia.test('Keycloak emite o token', () => insomnia.expect(insomnia.response.code).to.eql(200));
const corpo = insomnia.response.json();
insomnia.collectionVariables.set('token_loja_praia', corpo.access_token);
const conteudo = JSON.parse(atob(corpo.access_token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')));
insomnia.test('Token traz o comerciante c-002', () => insomnia.expect(conteudo.comerciante_id).to.eql('c-002'));
insomnia.test('Token tem a audiência verity-api', () => insomnia.expect([].concat(conteudo.aud)).to.include('verity-api'));
insomnia.test('Token assinado com RS256', () => insomnia.expect(JSON.parse(atob(corpo.access_token.split('.')[0].replace(/-/g, '+').replace(/_/g, '/'))).alg).to.eql('RS256'));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const saldo = insomnia.response.json();
insomnia.collectionVariables.set('base_saldo_final_hoje', String(saldo.saldoFinal));
insomnia.collectionVariables.set('base_creditos_hoje', String(saldo.totalCreditos));
insomnia.collectionVariables.set('base_debitos_hoje', String(saldo.totalDebitos));

insomnia.test('Lançamento criado (201)', () => insomnia.expect(insomnia.response.code).to.eql(201));
const corpo = insomnia.response.json();
insomnia.collectionVariables.set('id_credito_hoje', corpo.id);
const location = insomnia.response.headers.get('Location');
insomnia.test('Location aponta para o lançamento', () => insomnia.expect(String(location?.value ?? location)).to.include('/lancamentos/' + corpo.id));
insomnia.test('Tipo e valor gravados', () => { insomnia.expect(corpo.tipo).to.eql('Credito'); insomnia.expect(corpo.valor).to.eql(1000); });

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const pagina = insomnia.response.json();
insomnia.test('Extrato paginado', () => { insomnia.expect(pagina.pagina).to.eql(1); insomnia.expect(pagina.totalDeItens).to.be.at.least(3); });
if (pagina.totalDeItens <= 100) {
    const ids = pagina.itens.map(item => item.id);
    insomnia.test('Extrato contém os três lançamentos desta execução', () => {
        ['id_credito_hoje', 'id_debito_hoje', 'id_credito_retroativo'].forEach(nome => insomnia.expect(ids).to.include(insomnia.collectionVariables.get(nome)));
    });
}

insomnia.test('Estorno criado (201)', () => insomnia.expect(insomnia.response.code).to.eql(201));
const estorno = insomnia.response.json();
insomnia.collectionVariables.set('id_estorno_debito', estorno.id);
insomnia.test('Estorno é um crédito de mesmo valor ligado ao débito', () => {
    insomnia.expect(estorno.tipo).to.eql('Credito');
    insomnia.expect(estorno.valor).to.eql(250.5);
    insomnia.expect(estorno.estornoDeId).to.eql(insomnia.collectionVariables.get('id_debito_hoje'));
});

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const ids = insomnia.response.json().itens.map(item => item.id);
insomnia.test('Nenhum lançamento da loja.centro aparece', () =>
    ['id_credito_hoje', 'id_debito_hoje', 'id_credito_retroativo'].forEach(nome => insomnia.expect(ids).to.not.include(insomnia.collectionVariables.get(nome))));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const centavos = valor => Math.round(Number(valor) * 100);
const variavel = nome => insomnia.collectionVariables.get(nome);
const saldo = insomnia.response.json();
insomnia.test('Saldo final = base + 1.300,00', () => insomnia.expect(centavos(saldo.saldoFinal)).to.eql(centavos(variavel('base_saldo_final_hoje')) + 130000));
insomnia.test('Créditos do dia = base + 1.250,50', () => insomnia.expect(centavos(saldo.totalCreditos)).to.eql(centavos(variavel('base_creditos_hoje')) + 125050));
insomnia.test('Débitos do dia = base + 250,50', () => insomnia.expect(centavos(saldo.totalDebitos)).to.eql(centavos(variavel('base_debitos_hoje')) + 25050));
insomnia.test('Saldo inicial + créditos − débitos = saldo final', () =>
    insomnia.expect(centavos(saldo.saldoInicial) + centavos(saldo.totalCreditos) - centavos(saldo.totalDebitos)).to.eql(centavos(saldo.saldoFinal)));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const centavos = valor => Math.round(Number(valor) * 100);
const variavel = nome => insomnia.collectionVariables.get(nome);
insomnia.test('Saldo final do dia retroativo = base + 300,00', () =>
    insomnia.expect(centavos(insomnia.response.json().saldoFinal)).to.eql(centavos(variavel('base_saldo_final_retroativo')) + 30000));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const centavos = valor => Math.round(Number(valor) * 100);
const variavel = nome => insomnia.collectionVariables.get(nome);
const dias = insomnia.response.json();
insomnia.test('Um item por dia do período (7 dias)', () => insomnia.expect(dias.length).to.eql(7));
insomnia.test('Saldo inicial de cada dia = saldo final do dia anterior', () => {
    for (let indice = 1; indice < dias.length; indice++)
        insomnia.expect(centavos(dias[indice].saldoInicial)).to.eql(centavos(dias[indice - 1].saldoFinal));
});
insomnia.test('Último dia do período = saldo de hoje', () =>
    insomnia.expect(centavos(dias[dias.length - 1].saldoFinal)).to.eql(centavos(variavel('base_saldo_final_hoje')) + 130000));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
insomnia.test('Saldo pertence ao comerciante c-002 (sem os 1.300,00 da loja.centro)', () =>
    insomnia.expect(Number(insomnia.response.json().saldoFinal)).to.not.eql(Number(insomnia.collectionVariables.get('base_saldo_final_hoje')) + 1300));

insomnia.test('Status 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
const centavos = valor => Math.round(Number(valor) * 100);
const variavel = nome => insomnia.collectionVariables.get(nome);
insomnia.test('Saldo final = base da demonstração + 500,00', () =>
    insomnia.expect(centavos(insomnia.response.json().saldoFinal)).to.eql(centavos(variavel('base_resiliencia')) + 50000));
